import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.DgVVaeR-.js";const _=JSON.parse('{"title":"ライブ壁紙とウィジェット","description":"","frontmatter":{"title":"ライブ壁紙とウィジェット"},"headers":[],"relativePath":"user/wallpaper-widget.md","filePath":"user/wallpaper-widget.md","lastUpdated":1791002672000}'),i={name:"user/wallpaper-widget.md"};function o(s,a,n,p,d,h){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="ライブ壁紙とウィジェット" tabindex="-1">ライブ壁紙とウィジェット <a class="header-anchor" href="#ライブ壁紙とウィジェット" aria-label="Permalink to &quot;ライブ壁紙とウィジェット&quot;">​</a></h1><h2 id="壁紙の画像ソース" tabindex="-1">壁紙の画像ソース <a class="header-anchor" href="#壁紙の画像ソース" aria-label="Permalink to &quot;壁紙の画像ソース&quot;">​</a></h2><p>ライブ壁紙の画像ソースは、<strong>保存済み画像</strong>または<strong>選択した端末内フォルダ</strong>です。Pixivのブックマークやタグを直接検索して壁紙にする設定ではありません。使用したい作品を先に保存するか、フォルダへの読み取りを許可してください。</p><p>切り替え契機・時間間隔、並び順、拡大方法、背景、クロスフェード、センシティブ作品の除外を設定できます。別の壁紙プレイリスト処理には、保存画像を約6時間間隔の非厳密アラームで切り替える実装もあります。</p><p>ライブ壁紙は、アプリがデスクトップ環境・WSA・HyperOS端末と判定した場合には無効になります。</p><h2 id="イラストウィジェット" tabindex="-1">イラストウィジェット <a class="header-anchor" href="#イラストウィジェット" aria-label="Permalink to &quot;イラストウィジェット&quot;">​</a></h2><ol><li>ホームアプリのウィジェット一覧からPalleriaのイラストウィジェットを追加します。</li><li>Palleriaへログインし、設定画面で作品と表示するページを選びます。</li><li>適用すると選択画像を端末内へ保持して表示します。画像をタップすると該当作品を開きます。</li></ol><p>画像ファイルが失われた場合は再設定の案内が表示されます。表示が空白になった場合は、ウィジェットをタップして作品を選び直してください。プライバシーモード中は作品画像を表示しません。</p><h2 id="ランキングウィジェット" tabindex="-1">ランキングウィジェット <a class="header-anchor" href="#ランキングウィジェット" aria-label="Permalink to &quot;ランキングウィジェット&quot;">​</a></h2><p>デイリーランキングからフィルター適用後の<strong>最大3作品</strong>を表示します。TOP 10をスライドする形式ではありません。ログイン状態が必要で、プライバシーモード中は取得・表示が制限されます。</p><p>ウィジェットのサイズや配置操作はホームアプリによって異なります。</p>',11)])])}const u=e(i,[["render",o]]);export{_ as __pageData,u as default};
